const {useState:useStateCom,useEffect:useEffectCom,useMemo:useMemoCom}=React;
const CAPI=EnvoxersAPI.api;
const CUPLOAD=EnvoxersAPI.upload;
let commercialMetaCache=null;
let commercialMetaPromise=null;
function CLoadMeta(){
  if(commercialMetaCache)return Promise.resolve(commercialMetaCache);
  if(!commercialMetaPromise){
    commercialMetaPromise=CAPI('/comercial/meta').then(r=>{commercialMetaCache=r;return r}).finally(()=>{commercialMetaPromise=null});
  }
  return commercialMetaPromise;
}
const cFmtDate=v=>{if(!v)return '—';const s=String(v);if(/^\d{4}-\d{2}-\d{2}$/.test(s)){const [y,m,d]=s.split('-');return `${d}/${m}/${y}`}return new Date(v).toLocaleDateString('pt-BR')};
const cFmtDT=v=>v?new Date(v).toLocaleString('pt-BR'):'—';
const cDateInput=v=>{if(!v)return '';const d=new Date(v);const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`};
const cStatus=s=>(s||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const cMoney=v=>v==null||v===''?'—':Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const cOrigin=s=>({prospeccao_ativa:'Prospecção ativa',google:'Google',instagram:'Instagram',indicacao:'Indicação',evento:'Evento',lista:'Lista',importacao:'Importação',outro:'Outro'}[s]||cStatus(s));
const cChannel=s=>({google_maps:'Google Maps',cardapio_digital:'Cardápio digital',ifood:'iFood','99food':'99Food',whatsapp:'WhatsApp',email:'E-mail'}[s]||cStatus(s));
const cEmpty=v=>v==null||v==='';

function CModal({title,onClose,children,wide=false}){return <div className="modal-overlay open commercial-modal-overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal commercial-modal" style={{maxWidth:wide?980:720}}><div className="modal-head"><h2 className="modal-title">{title}</h2><button className="modal-close" onClick={onClose} aria-label="Fechar">×</button></div><div className="modal-body"><div className="modal-main">{children}</div></div></div></div>}
function CError({error}){return error?<div className="commercial-error">{error}</div>:null}
function CEmpty({children}){return <div className="empty-state">{children}</div>}
function CSpinner(){return <div className="empty-state">Carregando…</div>}
function CBadge({children,tone=''}){return <span className={'commercial-badge '+tone}>{children}</span>}
function CField({label,children,span=false}){return <div className={'field'+(span?' span-2':'')}><label>{label}</label>{children}</div>}
function CSectionTitle({title,action}){return <div className="commercial-section-title"><h3>{title}</h3>{action}</div>}

function LeadFormModal({lead,meta,onClose,onSaved}){
  const channels0={};(lead?.canais||[]).forEach(x=>channels0[x.tipo]=x.valor);
  const l=lead?.lead||lead||{};const contact=lead?.contatos?.find(x=>x.principal)||lead?.contatos?.[0]||{};
  const [f,setF]=useStateCom({data_entrada:l.data_entrada||new Date().toISOString().slice(0,10),nome_estabelecimento:l.nome_estabelecimento||'',nome_fantasia:l.nome_fantasia||'',segmento:l.segmento||'',subsegmento:l.subsegmento||'',cidade:l.cidade||'',estado:l.estado||'PR',bairro:l.bairro||'',telefone:l.telefone||'',whatsapp:l.whatsapp||'',email:l.email||'',origem:l.origem||'prospeccao_ativa',responsavel_envoxer_id:l.responsavel_envoxer_id||'',status_codigo:l.status_codigo||'novo',observacoes:l.observacoes||'',proxima_acao:l.proxima_acao||'',proxima_acao_em:cDateInput(l.proxima_acao_em),channels:channels0,contato_nome:contact.nome||'',contato_cargo:contact.cargo||'',contato_telefone:contact.telefone||'',contato_whatsapp:contact.whatsapp||'',contato_email:contact.email||''});
  const [saving,setSaving]=useStateCom(false),[error,setError]=useStateCom('');const set=(k,v)=>setF(x=>({...x,[k]:v}));
  const save=async()=>{setSaving(true);setError('');try{const payload={...f,responsavel_envoxer_id:f.responsavel_envoxer_id?Number(f.responsavel_envoxer_id):null,proxima_acao_em:f.proxima_acao_em?new Date(f.proxima_acao_em).toISOString():null};delete payload.channels;delete payload.contato_nome;delete payload.contato_cargo;delete payload.contato_telefone;delete payload.contato_whatsapp;delete payload.contato_email;if(l.id){await CAPI(`/comercial/leads/${l.id}`,{method:'PATCH',body:JSON.stringify(payload)});for(const [tipo,valor] of Object.entries(f.channels)){if(valor){await CAPI(`/comercial/leads/${l.id}/canais`,{method:'POST',body:JSON.stringify({tipo,valor})})}else{const existing=(lead?.canais||[]).find(x=>x.tipo===tipo&&x.ativo);if(existing)await CAPI(`/comercial/leads/${l.id}/canais/${existing.id}`,{method:'DELETE'})}}}else{payload.canais=f.channels;payload.contato=f.contato_nome?{nome:f.contato_nome,cargo:f.contato_cargo,telefone:f.contato_telefone,whatsapp:f.contato_whatsapp,email:f.contato_email}:null;await CAPI('/comercial/leads',{method:'POST',body:JSON.stringify(payload)})}onSaved()}catch(e){setError(e.message)}finally{setSaving(false)}};
  return <CModal title={l.id?'Editar lead':'Novo lead'} onClose={onClose} wide><CError error={error}/><div className="commercial-form-block"><h4>Estabelecimento</h4><div className="form-grid"><CField label="Data de entrada"><input type="date" value={f.data_entrada} onChange={e=>set('data_entrada',e.target.value)}/></CField><CField label="Nome do estabelecimento *"><input value={f.nome_estabelecimento} onChange={e=>set('nome_estabelecimento',e.target.value)}/></CField><CField label="Nome fantasia"><input value={f.nome_fantasia} onChange={e=>set('nome_fantasia',e.target.value)}/></CField><CField label="Segmento"><input value={f.segmento} onChange={e=>set('segmento',e.target.value)} placeholder="Restaurante, café, bar..."/></CField><CField label="Subsegmento"><input value={f.subsegmento} onChange={e=>set('subsegmento',e.target.value)}/></CField><CField label="Cidade"><input value={f.cidade} onChange={e=>set('cidade',e.target.value)}/></CField><CField label="Estado"><input value={f.estado} onChange={e=>set('estado',e.target.value)}/></CField><CField label="Bairro"><input value={f.bairro} onChange={e=>set('bairro',e.target.value)}/></CField><CField label="Telefone"><input value={f.telefone} onChange={e=>set('telefone',e.target.value)}/></CField><CField label="WhatsApp"><input value={f.whatsapp} onChange={e=>set('whatsapp',e.target.value)}/></CField><CField label="E-mail"><input type="email" value={f.email} onChange={e=>set('email',e.target.value)}/></CField><CField label="Origem"><select value={f.origem} onChange={e=>set('origem',e.target.value)}>{meta.origens.map(x=><option value={x} key={x}>{cOrigin(x)}</option>)}</select></CField><CField label="Responsável Envox"><select value={f.responsavel_envoxer_id} onChange={e=>set('responsavel_envoxer_id',e.target.value)}><option value="">Sem responsável</option>{meta.users.map(x=><option value={x.id} key={x.id}>{x.nome}</option>)}</select></CField><CField label="Status"><select value={f.status_codigo} onChange={e=>set('status_codigo',e.target.value)}>{meta.stages.map(x=><option value={x.codigo} key={x.codigo}>{x.nome}</option>)}</select></CField><CField label="Próxima ação" span><input value={f.proxima_acao} onChange={e=>set('proxima_acao',e.target.value)}/></CField><CField label="Data da próxima ação"><input type="datetime-local" value={f.proxima_acao_em} onChange={e=>set('proxima_acao_em',e.target.value)}/></CField><CField label="Observações" span><textarea rows="3" value={f.observacoes} onChange={e=>set('observacoes',e.target.value)}/></CField></div></div>
  <div className="commercial-form-block"><h4>Canais digitais</h4><div className="form-grid">{meta.canais.map(tipo=><CField label={cChannel(tipo)} key={tipo}><input value={f.channels[tipo]||''} onChange={e=>setF(x=>({...x,channels:{...x.channels,[tipo]:e.target.value}}))} placeholder={tipo==='instagram'?'@perfil ou URL':'URL'}/></CField>)}</div></div>
  {!l.id&&<div className="commercial-form-block"><h4>Contato principal</h4><div className="form-grid"><CField label="Nome"><input value={f.contato_nome} onChange={e=>set('contato_nome',e.target.value)}/></CField><CField label="Cargo"><input value={f.contato_cargo} onChange={e=>set('contato_cargo',e.target.value)}/></CField><CField label="Telefone"><input value={f.contato_telefone} onChange={e=>set('contato_telefone',e.target.value)}/></CField><CField label="WhatsApp"><input value={f.contato_whatsapp} onChange={e=>set('contato_whatsapp',e.target.value)}/></CField><CField label="E-mail"><input value={f.contato_email} onChange={e=>set('contato_email',e.target.value)}/></CField></div></div>}
  <div className="modal-footer"><button className="btn" onClick={onClose}>Cancelar</button><button className="btn btn-envox" disabled={!f.nome_estabelecimento.trim()||saving} onClick={save}>{saving?'Salvando…':l.id?'Salvar alterações':'Criar lead'}</button></div></CModal>
}

function ImportModal({onClose,onDone}){const [preview,setPreview]=useStateCom(null),[mapping,setMapping]=useStateCom({}),[strategy,setStrategy]=useStateCom('skip'),[busy,setBusy]=useStateCom(false),[error,setError]=useStateCom('');const choose=async e=>{const file=e.target.files?.[0];if(!file)return;setBusy(true);setError('');try{const r=await CUPLOAD('/comercial/importar/preview',file,file.name);setPreview(r);setMapping(r.mapeamento_sugerido||{})}catch(err){setError(err.message)}finally{setBusy(false)}};const commit=async()=>{setBusy(true);setError('');try{const r=await CAPI('/comercial/importar/commit',{method:'POST',body:JSON.stringify({rows:preview.rows,mapping,duplicate_strategy:strategy})});alert(`Importação concluída: ${r.criados} criados, ${r.atualizados} atualizados, ${r.ignorados} ignorados.`);onDone()}catch(e){setError(e.message)}finally{setBusy(false)}};return <CModal title="Importar leads · CSV ou XLSX" onClose={onClose} wide><CError error={error}/><div className="commercial-import-drop"><input type="file" accept=".csv,.xlsx" onChange={choose}/><div><b>Selecione sua planilha</b><span>CSV ou XLSX · até 5.000 linhas</span></div></div>{busy&&!preview&&<CSpinner/>}{preview&&<><div className="commercial-import-summary"><b>{preview.total}</b> linhas encontradas <span>·</span> <b>{preview.duplicados?.length||0}</b> possíveis duplicados na prévia</div><div className="commercial-map-grid">{preview.colunas.map(col=><div className="commercial-map" key={col}><span>{col}</span><span>→</span><select value={mapping[col]||''} onChange={e=>setMapping(x=>({...x,[col]:e.target.value||null}))}><option value="">Ignorar</option>{preview.campos_destino.map(f=><option key={f} value={f}>{cStatus(f)}</option>)}</select></div>)}</div><div className="field" style={{marginTop:16}}><label>Se encontrar duplicado</label><select value={strategy} onChange={e=>setStrategy(e.target.value)}><option value="skip">Não cadastrar / manter existente</option><option value="update">Atualizar lead existente com dados da planilha</option></select></div><div className="table-wrap commercial-preview"><table><thead><tr>{preview.colunas.slice(0,6).map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{preview.preview.slice(0,8).map((row,i)=><tr key={i}>{preview.colunas.slice(0,6).map(c=><td key={c}>{String(row[c]||'')}</td>)}</tr>)}</tbody></table></div></>}<div className="modal-footer"><button className="btn" onClick={onClose}>Cancelar</button>{preview&&<button className="btn btn-envox" onClick={commit} disabled={busy}>{busy?'Importando…':'Importar agora'}</button>}</div></CModal>}

function SimpleFormModal({title,onClose,onSave,fields,submit='Salvar'}){const [f,setF]=useStateCom(()=>Object.fromEntries(fields.map(x=>[x.key,x.value??'']))),[busy,setBusy]=useStateCom(false),[error,setError]=useStateCom('');const save=async()=>{setBusy(true);setError('');try{await onSave(f)}catch(e){setError(e.message);setBusy(false)}};return <CModal title={title} onClose={onClose}><CError error={error}/><div className="form-grid">{fields.map(x=><CField label={x.label} span={x.span} key={x.key}>{x.type==='textarea'?<textarea rows={x.rows||4} value={f[x.key]} onChange={e=>setF({...f,[x.key]:e.target.value})}/>:x.type==='select'?<select value={f[x.key]} onChange={e=>setF({...f,[x.key]:e.target.value})}>{x.options.map(o=><option value={o.value} key={o.value}>{o.label}</option>)}</select>:x.type==='multiselect'?<div className="commercial-checklist">{x.options.map(o=>{const arr=Array.isArray(f[x.key])?f[x.key]:[];return <label key={o.value}><input type="checkbox" checked={arr.includes(o.value)} onChange={e=>setF({...f,[x.key]:e.target.checked?[...arr,o.value]:arr.filter(v=>v!==o.value)})}/>{o.label}</label>})}</div>:<input type={x.type||'text'} value={f[x.key]} onChange={e=>setF({...f,[x.key]:e.target.value})}/>}</CField>)}</div><div className="modal-footer"><button className="btn" onClick={onClose}>Cancelar</button><button className="btn btn-envox" disabled={busy} onClick={save}>{busy?'Salvando…':submit}</button></div></CModal>}

function MessageModal({lead,data,meta,onClose,onDone,defaultDirection='enviada'}){const [f,setF]=useStateCom({direcao:defaultDirection,canal:'instagram',tipo:defaultDirection==='recebida'?'resposta':'abordagem',conteudo:'',insight_id:'',objecao_categoria:''}),[busy,setBusy]=useStateCom(false),[error,setError]=useStateCom('');const save=async()=>{setBusy(true);setError('');try{await CAPI(`/comercial/leads/${lead.id}/mensagens`,{method:'POST',body:JSON.stringify({...f,insight_id:f.insight_id?Number(f.insight_id):null})});onDone()}catch(e){setError(e.message);setBusy(false)}};return <CModal title={f.direcao==='recebida'?'Registrar resposta do lead':'Registrar contato enviado'} onClose={onClose}><CError error={error}/><div className="form-grid"><CField label="Direção"><select value={f.direcao} onChange={e=>setF({...f,direcao:e.target.value,tipo:e.target.value==='recebida'?'resposta':'abordagem'})}><option value="enviada">Enviada</option><option value="recebida">Recebida</option></select></CField><CField label="Canal"><select value={f.canal} onChange={e=>setF({...f,canal:e.target.value})}>{meta.canais_mensagem.map(x=><option value={x} key={x}>{cChannel(x)}</option>)}</select></CField><CField label="Tipo"><select value={f.tipo} onChange={e=>setF({...f,tipo:e.target.value})}>{meta.tipos_mensagem.map(x=><option value={x} key={x}>{cStatus(x)}</option>)}</select></CField>{f.direcao==='recebida'&&<CField label="Objeção (se houver)"><select value={f.objecao_categoria} onChange={e=>setF({...f,objecao_categoria:e.target.value})}><option value="">Nenhuma / não classificada</option>{meta.objecoes.map(x=><option value={x} key={x}>{cStatus(x)}</option>)}</select></CField>}{f.direcao==='enviada'&&<CField label="Ouro utilizado"><select value={f.insight_id} onChange={e=>setF({...f,insight_id:e.target.value})}><option value="">Nenhum</option>{data.ouros.filter(x=>!x.utilizado).map(x=><option value={x.id} key={x.id}>{x.titulo}</option>)}</select></CField>}<CField label="Mensagem" span><textarea rows="7" value={f.conteudo} onChange={e=>setF({...f,conteudo:e.target.value})}/></CField></div><div className="modal-footer"><button className="btn" onClick={onClose}>Cancelar</button><button className="btn btn-envox" onClick={save} disabled={busy||!f.conteudo.trim()}>{busy?'Registrando…':'Registrar contato'}</button></div></CModal>}

function DraftModal({lead,draft,onClose,onSent}){const [busy,setBusy]=useStateCom(false),[text,setText]=useStateCom(draft.mensagem||''),[error,setError]=useStateCom('');const channel=draft.canal||'instagram';const openChannel=()=>{if(channel==='whatsapp'){const n=(lead.whatsapp||'').replace(/\D/g,'');if(n)window.open(`https://wa.me/${n}?text=${encodeURIComponent(text)}`,'_blank')}else if(channel==='email'&&lead.email){window.location.href=`mailto:${lead.email}?body=${encodeURIComponent(text)}`}else{window.open('https://www.instagram.com/','_blank')}};const sent=async()=>{setBusy(true);setError('');try{await CAPI(`/comercial/leads/${lead.id}/mensagens`,{method:'POST',body:JSON.stringify({direcao:'enviada',canal:channel,tipo:draft.interpretacao?'conversa':'abordagem',conteudo:text,insight_id:draft.insight_id||null,gerado_por_ia:true})});onSent()}catch(e){setError(e.message);setBusy(false)}};return <CModal title="Mensagem gerada pela IA" onClose={onClose}><CError error={error}/>{draft.interpretacao&&<div className="commercial-interpret"><b>Interpretação</b><div><span>Tipo:</span> {draft.interpretacao.tipo||'—'}</div><div><span>Sentimento:</span> {draft.interpretacao.sentimento||'—'}</div><div><span>Intenção:</span> {draft.interpretacao.intencao||'—'}</div><div><span>Objeção:</span> {draft.interpretacao.objecao||'—'}</div><div><span>Próximo passo:</span> {draft.interpretacao.proximo_passo||'—'}</div></div>}<textarea className="commercial-draft-edit" rows="9" value={text} onChange={e=>setText(e.target.value)}/><div className="commercial-draft-note">Gerar não conta como envio. O ouro só será marcado como utilizado quando você confirmar “Marcar como enviada”.</div><div className="modal-footer"><button className="btn" onClick={()=>navigator.clipboard.writeText(text)}>Copiar mensagem</button><button className="btn" onClick={openChannel}>Abrir {cChannel(channel)}</button><button className="btn btn-envox" onClick={sent} disabled={busy||!text.trim()}>{busy?'Registrando…':'Marcar como enviada'}</button></div></CModal>}

function GenerateModal({data,meta,onClose,onGenerated,next=false}){const [canal,setCanal]=useStateCom('instagram'),[ouro,setOuro]=useStateCom(''),[busy,setBusy]=useStateCom(false),[error,setError]=useStateCom('');const run=async()=>{setBusy(true);setError('');try{const r=next?await CAPI(`/comercial/leads/${data.lead.id}/gerar-resposta`,{method:'POST'}):await CAPI(`/comercial/leads/${data.lead.id}/gerar-mensagem`,{method:'POST',body:JSON.stringify({canal,insight_id:ouro?Number(ouro):null})});if(!next)r.canal=canal;onGenerated(r)}catch(e){setError(e.message);setBusy(false)}};return <CModal title={next?'Gerar próxima resposta':'Gerar abordagem'} onClose={onClose}><CError error={error}/>{!next&&<div className="form-grid"><CField label="Canal"><select value={canal} onChange={e=>setCanal(e.target.value)}>{meta.canais_mensagem.map(x=><option value={x} key={x}>{cChannel(x)}</option>)}</select></CField><CField label="Ouro"><select value={ouro} onChange={e=>setOuro(e.target.value)}><option value="">Escolher automaticamente o melhor disponível</option>{data.ouros.filter(x=>!x.utilizado&&x.ativo).map(x=><option value={x.id} key={x.id}>{x.titulo}</option>)}</select></CField></div>}{next&&<p>A IA receberá toda a conversa deste lead, os ouros usados, os ouros disponíveis e o status comercial. Ela gerará somente a próxima mensagem.</p>}<div className="modal-footer"><button className="btn" onClick={onClose}>Cancelar</button><button className="btn btn-envox" onClick={run} disabled={busy}>{busy?'Gerando…':'Gerar agora'}</button></div></CModal>}

function LeadDetail({leadId,onBack,meta}){
 const [data,setData]=useStateCom(null),[modal,setModal]=useStateCom(null),[draft,setDraft]=useStateCom(null),[busy,setBusy]=useStateCom(''),[tab,setTab]=useStateCom('resumo'),[error,setError]=useStateCom('');
 const load=()=>CAPI(`/comercial/leads/${leadId}`).then(setData).catch(e=>setError(e.message));useEffectCom(()=>{load()},[leadId]);if(!data)return error?<CError error={error}/>:<CSpinner/>;const l=data.lead;
 const patch=async payload=>{await CAPI(`/comercial/leads/${l.id}`,{method:'PATCH',body:JSON.stringify(payload)});await load()};
 const runAudit=async()=>{setBusy('audit');setError('');try{await CAPI(`/comercial/leads/${l.id}/analisar`,{method:'POST'});await load();setTab('auditoria')}catch(e){setError(e.message)}finally{setBusy('')}};
 const addSource=()=>setModal({type:'simple',title:'Adicionar evidência pública',fields:[{key:'tipo',label:'Tipo',type:'select',value:'google',options:['google','instagram','tripadvisor','ifood','site','cardapio','facebook','outro'].map(x=>({value:x,label:cStatus(x)}))},{key:'fonte',label:'Fonte'},{key:'url',label:'URL'},{key:'evidencia',label:'Trecho / evidência',type:'textarea',span:true}],save:async f=>{await CAPI(`/comercial/leads/${l.id}/fontes`,{method:'POST',body:JSON.stringify(f)});setModal(null);await load()}});
 const addGold=()=>setModal({type:'simple',title:'Adicionar ouro manual',fields:[{key:'categoria',label:'Categoria',type:'select',value:'outro',options:meta.categorias_ouro.map(x=>({value:x,label:cStatus(x)}))},{key:'grau_confianca',label:'Grau de confiança',type:'select',value:'medio',options:['alto','medio','baixo'].map(x=>({value:x,label:cStatus(x)}))},{key:'titulo',label:'Título',span:true},{key:'evidencia',label:'Evidência',type:'textarea',span:true},{key:'impacto',label:'Impacto comercial',type:'textarea',span:true},{key:'fonte',label:'Fonte',span:true}],save:async f=>{await CAPI(`/comercial/leads/${l.id}/ouros`,{method:'POST',body:JSON.stringify(f)});setModal(null);await load()}});
 const addTask=()=>setModal({type:'simple',title:'Adicionar tarefa comercial',fields:[{key:'titulo',label:'Tarefa',span:true},{key:'prazo',label:'Prazo',type:'datetime-local'},{key:'responsavel_envoxer_id',label:'Responsável',type:'select',value:String(l.responsavel_envoxer_id||''),options:[{value:'',label:'Sem responsável'},...meta.users.map(x=>({value:String(x.id),label:x.nome}))]},{key:'descricao',label:'Descrição',type:'textarea',span:true}],save:async f=>{await CAPI(`/comercial/leads/${l.id}/tarefas`,{method:'POST',body:JSON.stringify({...f,responsavel_envoxer_id:f.responsavel_envoxer_id?Number(f.responsavel_envoxer_id):null,prazo:f.prazo?new Date(f.prazo).toISOString():null})});setModal(null);await load()}});
 const addContact=()=>setModal({type:'simple',title:'Adicionar contato',fields:[{key:'nome',label:'Nome'},{key:'cargo',label:'Cargo'},{key:'telefone',label:'Telefone'},{key:'whatsapp',label:'WhatsApp'},{key:'email',label:'E-mail'}],save:async f=>{await CAPI(`/comercial/leads/${l.id}/contatos`,{method:'POST',body:JSON.stringify(f)});setModal(null);await load()}});
 const editContact=x=>setModal({type:'simple',title:'Editar contato',fields:[{key:'nome',label:'Nome',value:x.nome||''},{key:'cargo',label:'Cargo',value:x.cargo||''},{key:'telefone',label:'Telefone',value:x.telefone||''},{key:'whatsapp',label:'WhatsApp',value:x.whatsapp||''},{key:'email',label:'E-mail',value:x.email||''}],save:async f=>{await CAPI(`/comercial/leads/${l.id}/contatos/${x.id}`,{method:'PATCH',body:JSON.stringify(f)});setModal(null);await load()}});
 const addChannel=()=>setModal({type:'simple',title:'Adicionar / atualizar canal',fields:[{key:'tipo',label:'Canal',type:'select',value:'instagram',options:meta.canais.map(x=>({value:x,label:cChannel(x)}))},{key:'valor',label:'URL / perfil / endereço',span:true}],save:async f=>{await CAPI(`/comercial/leads/${l.id}/canais`,{method:'POST',body:JSON.stringify(f)});setModal(null);await load()}});
 const addMemory=()=>setModal({type:'simple',title:'Adicionar memória do lead',fields:[{key:'tipo',label:'Tipo',type:'select',value:'fato',options:meta.tipos_fato.map(x=>({value:x,label:cStatus(x)}))},{key:'conteudo',label:'Conteúdo',type:'textarea',span:true}],save:async f=>{await CAPI(`/comercial/leads/${l.id}/memoria`,{method:'POST',body:JSON.stringify(f)});setModal(null);await load()}});
 const addOpp=()=>setModal({type:'simple',title:'Criar oportunidade',fields:[{key:'contato',label:'Contato',value:data.contatos?.[0]?.nome||''},{key:'probabilidade',label:'Probabilidade (%)',type:'number',value:'30'},{key:'dor_principal',label:'Dor principal',type:'textarea',span:true},{key:'solucao_provavel',label:'Solução provável',type:'textarea',span:true},{key:'servicos_relacionados',label:'Serviços relacionados',type:'multiselect',value:[],span:true,options:meta.services.map(x=>({value:x.slug||x.nome,label:x.nome}))},{key:'valor_estimado',label:'Valor estimado',type:'number'},{key:'data_prevista',label:'Data prevista',type:'date'},{key:'proxima_acao',label:'Próxima ação',span:true}],save:async f=>{await CAPI(`/comercial/leads/${l.id}/oportunidades`,{method:'POST',body:JSON.stringify(f)});setModal(null);await load();setTab('oportunidade')}});
 const editOpp=o=>setModal({type:'simple',title:'Editar oportunidade',fields:[{key:'contato',label:'Contato',value:o.contato||''},{key:'probabilidade',label:'Probabilidade (%)',type:'number',value:String(o.probabilidade||0)},{key:'dor_principal',label:'Dor principal',type:'textarea',span:true,value:o.dor_principal||''},{key:'solucao_provavel',label:'Solução provável',type:'textarea',span:true,value:o.solucao_provavel||''},{key:'servicos_relacionados',label:'Serviços relacionados',type:'multiselect',value:o.servicos_relacionados||[],span:true,options:meta.services.map(x=>({value:x.slug||x.nome,label:x.nome}))},{key:'valor_estimado',label:'Valor estimado',type:'number',value:o.valor_estimado||''},{key:'data_prevista',label:'Data prevista',type:'date',value:o.data_prevista||''},{key:'proxima_acao',label:'Próxima ação',span:true,value:o.proxima_acao||''},{key:'etapa',label:'Etapa',type:'select',value:o.etapa||'oportunidade',options:['oportunidade','reuniao_agendada','proposta','negociacao','ganho','perdido'].map(x=>({value:x,label:cStatus(x)}))}],save:async f=>{await CAPI(`/comercial/oportunidades/${o.id}`,{method:'PATCH',body:JSON.stringify({...f,probabilidade:Number(f.probabilidade||0),valor_estimado:f.valor_estimado?Number(f.valor_estimado):null})});setModal(null);await load()}});
 const startCadence=()=>setModal({type:'cadence'});
 const noProspect=async()=>{if(!confirm('Marcar este lead como NÃO PROSPECTAR? Isso encerra cadências e adiciona os contatos à lista de supressão.'))return;const motivo=prompt('Motivo:','Pedido para não contatar')||'Pedido para não contatar';await CAPI(`/comercial/leads/${l.id}/nao-prospectar`,{method:'POST',body:JSON.stringify({motivo})});await load()};
 const tabs=['resumo','dados','auditoria','ouros','mensagens','conversas','cadencia','tarefas','oportunidade','historico'];
 return <div className="commercial-detail"><div className="commercial-back" onClick={onBack}>← Voltar</div><CError error={error}/><div className="commercial-lead-head"><div><div className="commercial-eyebrow">LEAD #{l.id}</div><h1>{l.nome_estabelecimento}</h1><div className="page-sub">{l.segmento||'Sem segmento'} {l.subsegmento&&`· ${l.subsegmento}`} · {[l.bairro,l.cidade,l.estado].filter(Boolean).join(', ')||'Localização não informada'}</div><div className="commercial-badges"><CBadge tone={l.temperatura}>{l.temperatura}</CBadge><CBadge>Score {l.score_total}</CBadge>{l.tags?.map(t=><CBadge key={t.id}>{t.nome}</CBadge>)}</div></div><div className="commercial-head-controls"><label>Status<select value={l.status_codigo} onChange={e=>patch({status_codigo:e.target.value})}>{meta.stages.map(x=><option value={x.codigo} key={x.codigo}>{x.nome}</option>)}</select></label><label>Responsável<select value={l.responsavel_envoxer_id||''} onChange={e=>patch({responsavel_envoxer_id:e.target.value?Number(e.target.value):null})}><option value="">Sem responsável</option>{meta.users.map(x=><option value={x.id} key={x.id}>{x.nome}</option>)}</select></label></div></div>
 <div className="commercial-primary-actions"><button className="btn btn-envox" onClick={runAudit} disabled={!!busy}>{busy==='audit'?'Analisando…':'Analisar com IA'}</button><button className="btn" onClick={()=>setModal({type:'generate'})}>Gerar abordagem</button><button className="btn" onClick={()=>setModal({type:'message',direction:'enviada'})}>Registrar contato</button><button className="btn" onClick={addTask}>Adicionar tarefa</button><button className="btn" onClick={startCadence}>Iniciar cadência</button><button className="btn" onClick={addOpp}>Criar oportunidade</button><button className="btn" onClick={()=>setModal({type:'edit'})}>Editar lead</button><button className="btn" onClick={addSource}>+ Evidência</button><button className="btn danger-ghost" onClick={noProspect}>Não prospectar</button></div>
 <div className="commercial-tabs">{tabs.map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x==='cadencia'?'cadência':x}</button>)}</div>
 {tab==='resumo'&&<div className="commercial-grid"><div className="card"><CSectionTitle title="Próxima ação" action={<button className="btn btn-xs" onClick={()=>setModal({type:'next'})}>Editar</button>}/><div className="commercial-next">{l.proxima_acao||'Sem próxima ação definida'}</div><div className={l.proxima_acao_em&&new Date(l.proxima_acao_em)<new Date()?'commercial-due overdue':'commercial-due'}>{cFmtDT(l.proxima_acao_em)}</div></div><div className="card"><CSectionTitle title="Score do lead"/><div className="score-row"><span>Fit <b>{l.fit_score}</b></span><span>Oportunidade <b>{l.opportunity_score}</b></span><span>Engajamento <b>{l.engagement_score}</b></span><span>Total <b>{l.score_total}</b></span></div></div><div className="card"><CSectionTitle title="Ouros" action={<button className="btn btn-xs" onClick={()=>setTab('ouros')}>Ver todos</button>}/><div className="commercial-mini-kpis"><div><b>{data.ouros.filter(x=>!x.utilizado&&x.ativo).length}</b><span>disponíveis</span></div><div><b>{data.ouros.filter(x=>x.utilizado).length}</b><span>utilizados</span></div></div></div><div className="card"><CSectionTitle title="Contato"/><div className="commercial-contact-summary"><div><span>Último contato</span><b>{cFmtDT(l.ultimo_contato_em)}</b></div><div><span>Temperatura</span><b>{cStatus(l.temperatura)}</b></div></div></div><div className="card span-2"><CSectionTitle title="Tese comercial atual" action={<button className="btn btn-xs" onClick={()=>setTab('auditoria')}>Auditoria</button>}/><h3 className="commercial-thesis">{data.auditorias?.[0]?.tese_central||'Ainda não há auditoria deste lead.'}</h3><p>{data.auditorias?.[0]?.resumo||'Adicione fontes/evidências e execute a análise com IA quando a integração estiver configurada.'}</p></div><div className="card span-2"><CSectionTitle title="Memória específica deste lead" action={<button className="btn btn-xs" onClick={addMemory}>+ Adicionar</button>}/>{data.memoria.length?data.memoria.map(x=><div className="commercial-memory" key={x.id}><CBadge>{cStatus(x.tipo)}</CBadge><span>{x.conteudo}</span><button className="icon-btn" onClick={async()=>{await CAPI(`/comercial/leads/${l.id}/memoria/${x.id}`,{method:'DELETE'});load()}}>×</button></div>):<div className="muted">Sem fatos, hipóteses ou preferências registradas.</div>}</div></div>}
 {tab==='dados'&&<div className="commercial-grid"><div className="card"><CSectionTitle title="Dados cadastrais" action={<button className="btn btn-xs" onClick={()=>setModal({type:'edit'})}>Editar</button>}/>{[['Nome fantasia',l.nome_fantasia],['Origem',cOrigin(l.origem)],['Telefone',l.telefone],['WhatsApp',l.whatsapp],['E-mail',l.email],['Entrada',cFmtDate(l.data_entrada)]].map(([a,b])=><div className="commercial-line" key={a}><span>{a}</span><b>{b||'—'}</b></div>)}</div><div className="card"><CSectionTitle title="Contatos" action={<button className="btn btn-xs" onClick={addContact}>+ Contato</button>}/>{data.contatos.length?data.contatos.map(x=><div className="commercial-contact" key={x.id}><div><b>{x.nome}</b><span>{x.cargo||'Sem cargo'}</span><small>{[x.whatsapp,x.telefone,x.email].filter(Boolean).join(' · ')}</small></div><div className="commercial-inline-actions"><button className="btn btn-xs" onClick={()=>editContact(x)}>Editar</button><button className="icon-btn" onClick={async()=>{if(confirm('Remover contato?')){await CAPI(`/comercial/leads/${l.id}/contatos/${x.id}`,{method:'DELETE'});load()}}}>×</button></div></div>):<div className="muted">Nenhum contato cadastrado.</div>}</div><div className="card"><CSectionTitle title="Canais digitais" action={<button className="btn btn-xs" onClick={addChannel}>+ Canal</button>}/>{data.canais.length?data.canais.map(x=><div className="commercial-line" key={x.id}><span>{cChannel(x.tipo)}</span><a href={x.valor.startsWith('http')?x.valor:undefined} target="_blank">{x.valor}</a></div>):<div className="muted">Nenhum canal cadastrado.</div>}</div><div className="card"><CSectionTitle title="Tags" action={<button className="btn btn-xs" onClick={()=>{const n=prompt('Nova tag:');if(n)CAPI(`/comercial/leads/${l.id}/tags`,{method:'POST',body:JSON.stringify({nome:n})}).then(load)}}>+ Tag</button>}/>{l.tags?.length?<div className="commercial-tag-list">{l.tags.map(t=><span className="tag" key={t.id}>{t.nome}<button onClick={async()=>{await CAPI(`/comercial/leads/${l.id}/tags/${t.id}`,{method:'DELETE'});load()}}>×</button></span>)}</div>:<div className="muted">Sem tags.</div>}</div><div className="card span-2"><CSectionTitle title="Observações"/><div className="commercial-note">{l.observacoes||'Sem observações.'}</div></div></div>}
 {tab==='auditoria'&&<div><CSectionTitle title="Fontes e evidências" action={<button className="btn" onClick={addSource}>+ Adicionar evidência</button>}/><div className="commercial-sources">{data.fontes.length?data.fontes.map(x=><div className="card commercial-source" key={x.id}><div className="commercial-source-head"><CBadge>{cStatus(x.tipo)}</CBadge><span>{cFmtDT(x.consultado_em)}</span></div><b>{x.fonte||'Fonte pública'}</b><p>{x.evidencia}</p>{x.url&&<a href={x.url} target="_blank">Abrir fonte ↗</a>}</div>):<CEmpty>Nenhuma evidência adicionada. A IA não deve auditar sem contexto verificável.</CEmpty>}</div><CSectionTitle title="Auditorias realizadas"/><div className="commercial-audits">{data.auditorias.length?data.auditorias.map(a=><div className="card" key={a.id}><div className="commercial-audit-head"><div><CBadge>{a.prioridade||'sem prioridade'}</CBadge><CBadge>{a.risco_comercial||'risco não definido'}</CBadge></div><span>{cFmtDT(a.created_at)}</span></div><h3>{a.tese_central}</h3><p>{a.resumo}</p><div className="commercial-audit-cols"><div><b>Forças</b>{(a.forcas||[]).map((x,i)=><div key={i}>• {typeof x==='string'?x:JSON.stringify(x)}</div>)}</div><div><b>Vazamentos</b>{(a.vazamentos||[]).map((x,i)=><div key={i}>• {typeof x==='string'?x:JSON.stringify(x)}</div>)}</div><div><b>Oportunidades</b>{(a.oportunidades||[]).map((x,i)=><div key={i}>• {typeof x==='string'?x:JSON.stringify(x)}</div>)}</div><div><b>Observações</b>{(a.observacoes||[]).map((x,i)=><div key={i}>• {typeof x==='string'?x:JSON.stringify(x)}</div>)}</div></div></div>):<CEmpty>Nenhuma auditoria executada.</CEmpty>}</div></div>}
 {tab==='ouros'&&<div><CSectionTitle title="Biblioteca de ouros deste lead" action={<button className="btn btn-envox" onClick={addGold}>+ Ouro manual</button>}/><div className="commercial-golds">{data.ouros.length?data.ouros.map(o=><div className={'card commercial-gold '+(o.utilizado?'used':'')} key={o.id}><div className="commercial-gold-top"><CBadge>{cStatus(o.categoria||'outro')}</CBadge><button className="btn btn-xs" onClick={async()=>{await CAPI(`/comercial/leads/${l.id}/ouros/${o.id}`,{method:'PATCH',body:JSON.stringify({utilizado:!o.utilizado})});load()}}>{o.utilizado?'Marcar disponível':'Marcar utilizado'}</button></div><h3>{o.titulo}</h3><div><b>Evidência</b><p>{o.evidencia}</p></div><div><b>Impacto comercial</b><p>{o.impacto||'—'}</p></div><div className="muted">Fonte: {o.fonte||'não informada'} · confiança {o.grau_confianca}</div></div>):<CEmpty>Nenhum ouro encontrado.</CEmpty>}</div></div>}
 {(tab==='mensagens'||tab==='conversas')&&<div><div className="commercial-actions-left"><button className="btn btn-envox" onClick={()=>setModal({type:'generate'})}>Gerar abordagem</button><button className="btn" onClick={()=>setModal({type:'generateNext'})}>Gerar próxima resposta</button><button className="btn" onClick={()=>setModal({type:'message',direction:'enviada'})}>Registrar enviada</button><button className="btn" onClick={()=>setModal({type:'message',direction:'recebida'})}>Registrar resposta</button></div><div className="commercial-conversation">{data.mensagens.length?data.mensagens.map(m=><div className={'commercial-message '+m.direcao} key={m.id}><div className="commercial-message-meta"><span>{m.direcao==='enviada'?'Enviada':'Recebida'} · {cChannel(m.canal)} · {cStatus(m.tipo)}</span><span>{cFmtDT(m.enviado_em)}</span></div><div>{m.conteudo}</div>{m.insight_id&&<div className="commercial-message-gold">Ouro #{m.insight_id}</div>}{m.objecao_categoria&&<div className="commercial-message-gold">Objeção: {cStatus(m.objecao_categoria)}</div>}</div>):<CEmpty>Nenhuma conversa registrada.</CEmpty>}</div></div>}
 {tab==='cadencia'&&<div><CSectionTitle title="Cadência do lead" action={<button className="btn btn-envox" onClick={startCadence}>Iniciar cadência</button>}/>{data.cadencias.length?data.cadencias.map(c=><div className="card commercial-cadence" key={c.id}><div className="commercial-cadence-head"><div><h3>{c.nome}</h3><span>Iniciada em {cFmtDT(c.iniciada_em)}</span></div><CBadge tone={c.status==='ativa'?'quente':''}>{c.status}</CBadge></div><div className="commercial-steps">{c.steps.map(s=><div className={'commercial-step '+(s.ordem===c.proximo_step_ordem&&c.status==='ativa'?'active':'')} key={s.id}><b>D{s.dias_apos_inicio}</b><span>{cStatus(s.tipo)}</span><small>{s.orientacao}</small></div>)}</div>{c.status==='ativa'&&<div className="commercial-actions-left"><button className="btn btn-xs" onClick={async()=>{await CAPI(`/comercial/leads/${l.id}/cadencia/${c.id}`,{method:'PATCH',body:JSON.stringify({status:'pausada'})});load()}}>Pausar</button><button className="btn btn-xs" onClick={async()=>{await CAPI(`/comercial/leads/${l.id}/cadencia/${c.id}`,{method:'PATCH',body:JSON.stringify({status:'encerrada'})});load()}}>Encerrar</button></div>}</div>):<CEmpty>Este lead ainda não possui cadência.</CEmpty>}</div>}
 {tab==='tarefas'&&<div><CSectionTitle title="Tarefas comerciais" action={<button className="btn btn-envox" onClick={addTask}>+ Tarefa</button>}/>{data.tarefas.length?data.tarefas.map(t=><div className="card commercial-task" key={t.id}><button className={'commercial-check '+(t.status==='concluida'?'done':'')} onClick={async()=>{await CAPI(`/comercial/tarefas/${t.id}`,{method:'PATCH',body:JSON.stringify({status:t.status==='concluida'?'pendente':'concluida'})});load()}}>{t.status==='concluida'?'✓':''}</button><div><b>{t.titulo}</b><span>{t.descricao||''}</span></div><div className={t.status!=='concluida'&&t.prazo&&new Date(t.prazo)<new Date()?'commercial-due overdue':'commercial-due'}>{cFmtDT(t.prazo)}</div></div>):<CEmpty>Nenhuma tarefa.</CEmpty>}</div>}
 {tab==='oportunidade'&&<div><CSectionTitle title="Oportunidades" action={<button className="btn btn-envox" onClick={addOpp}>+ Oportunidade</button>}/>{data.oportunidades.length?data.oportunidades.map(o=><div className="card commercial-opportunity" key={o.id}><div><CBadge>{cStatus(o.etapa)}</CBadge><h3>{o.dor_principal||'Oportunidade comercial'}</h3><p>{o.solucao_provavel||'Solução ainda não definida.'}</p></div><div className="commercial-opportunity-numbers"><b>{cMoney(o.valor_estimado)}</b><span>{o.probabilidade}% prob.</span><small>{o.data_prevista?`Previsão ${cFmtDate(o.data_prevista)}`:'Sem previsão'}</small><button className="btn btn-xs" onClick={()=>editOpp(o)}>Editar</button></div></div>):<CEmpty>Nenhuma oportunidade criada.</CEmpty>}</div>}
 {tab==='historico'&&<div className="card commercial-timeline">{data.historico.length?data.historico.map(h=><div className="commercial-event" key={h.id}><div className="commercial-dot"></div><div><b>{h.descricao}</b><div className="muted">{cFmtDT(h.created_at)} · {cStatus(h.tipo)}</div></div></div>):<div className="muted">Sem histórico.</div>}</div>}
 {modal?.type==='edit'&&<LeadFormModal lead={data} meta={meta} onClose={()=>setModal(null)} onSaved={()=>{setModal(null);load()}}/>}
 {modal?.type==='message'&&<MessageModal lead={l} data={data} meta={meta} defaultDirection={modal.direction} onClose={()=>setModal(null)} onDone={()=>{setModal(null);load()}}/>}
 {modal?.type==='generate'&&<GenerateModal data={data} meta={meta} onClose={()=>setModal(null)} onGenerated={r=>{setModal(null);setDraft(r)}}/>}
 {modal?.type==='generateNext'&&<GenerateModal data={data} meta={meta} next onClose={()=>setModal(null)} onGenerated={r=>{r.canal=data.mensagens?.slice().reverse().find(x=>x.direcao==='recebida')?.canal||'instagram';setModal(null);setDraft(r)}}/>}
 {modal?.type==='next'&&<SimpleFormModal title="Definir próxima ação" onClose={()=>setModal(null)} fields={[{key:'proxima_acao',label:'Próxima ação',value:l.proxima_acao||'',span:true},{key:'proxima_acao_em',label:'Data e hora',type:'datetime-local',value:cDateInput(l.proxima_acao_em)}]} onSave={async f=>{await patch({proxima_acao:f.proxima_acao,proxima_acao_em:f.proxima_acao_em?new Date(f.proxima_acao_em).toISOString():null});setModal(null)}}/>}
 {modal?.type==='simple'&&<SimpleFormModal title={modal.title} fields={modal.fields} onClose={()=>setModal(null)} onSave={modal.save}/>}
 {modal?.type==='cadence'&&<CadenceStartModal lead={l} onClose={()=>setModal(null)} onDone={()=>{setModal(null);load();setTab('cadencia')}}/>}
 {draft&&<DraftModal lead={l} draft={draft} onClose={()=>setDraft(null)} onSent={()=>{setDraft(null);load();setTab('conversas')}}/>}
 </div>
}

function CadenceStartModal({lead,onClose,onDone}){const [items,setItems]=useStateCom([]),[id,setId]=useStateCom(''),[error,setError]=useStateCom('');useEffectCom(()=>{CAPI('/comercial/cadencias').then(r=>{setItems(r.filter(x=>x.ativa));if(r.find(x=>x.ativa))setId(String(r.find(x=>x.ativa).id))})},[]);const save=async()=>{try{await CAPI(`/comercial/leads/${lead.id}/cadencia`,{method:'POST',body:JSON.stringify({cadence_id:Number(id)})});onDone()}catch(e){setError(e.message)}};return <CModal title="Iniciar cadência" onClose={onClose}><CError error={error}/><div className="field"><label>Cadência</label><select value={id} onChange={e=>setId(e.target.value)}>{items.map(x=><option value={x.id} key={x.id}>{x.nome}</option>)}</select></div>{items.find(x=>String(x.id)===id)&&<div className="commercial-steps compact">{items.find(x=>String(x.id)===id).steps.map(s=><div className="commercial-step" key={s.id}><b>D{s.dias_apos_inicio}</b><span>{cStatus(s.tipo)}</span><small>{s.orientacao}</small></div>)}</div>}<div className="modal-footer"><button className="btn" onClick={onClose}>Cancelar</button><button className="btn btn-envox" disabled={!id} onClick={save}>Iniciar</button></div></CModal>}

function CommercialDashboard({onOpen}){const [d,setD]=useStateCom(null);useEffectCom(()=>{CAPI('/comercial/dashboard').then(setD)},[]);if(!d)return <CSpinner/>;const k=[['Leads',d.leads],['Novos',d.novos],['Analisados',d.analisados],['Mensagens',d.mensagens_enviadas],['Respostas',d.respostas],['Taxa de resposta',d.taxa_resposta+'%'],['Conversas abertas',d.conversas],['Reuniões',d.reunioes],['Propostas',d.propostas],['Ganhos',d.ganhos],['Perdidos',d.perdidos]];const max=Math.max(1,...d.funnel.map(x=>x.value));return <div><div className="commercial-kpis">{k.map(([a,b])=><div className="kpi" key={a}><div className="kpi-label">{a}</div><div className="kpi-value">{b}</div></div>)}</div><div className="commercial-dashboard-grid"><div className="card"><CSectionTitle title="Funil comercial"/><div className="commercial-funnel">{d.funnel.map(x=><div className="commercial-funnel-row" key={x.key}><span>{x.label}</span><div><i style={{width:`${Math.max(3,x.value/max*100)}%`}}></i></div><b>{x.value}</b></div>)}</div></div><div className="card"><CSectionTitle title="Mais próximos de virar oportunidade"/>{d.top_leads.length?d.top_leads.map(x=><div className="commercial-lead-mini" key={x.id} onClick={()=>onOpen(x.id)}><div><b>{x.nome_estabelecimento}</b><span>{x.segmento||'Sem segmento'} · {x.cidade||'Sem cidade'}</span></div><div><b>{x.score_total}</b><small>{cStatus(x.status_codigo)}</small></div></div>):<CEmpty>Nenhum lead cadastrado.</CEmpty>}</div></div></div>}

function CommercialToday({onOpen}){const [d,setD]=useStateCom(null);const load=()=>CAPI('/comercial/hoje').then(setD);useEffectCom(()=>{load()},[]);if(!d)return <CSpinner/>;return <div><div className="commercial-today-head"><div className="commercial-today-number">{d.total}</div><div><b>ações comerciais pedindo atenção</b><span>O objetivo desta tela é dizer exatamente o que precisa acontecer agora.</span></div></div>{d.sections.map(s=><div className="commercial-today-section" key={s.key}><CSectionTitle title={`${s.label} · ${s.items.length}`}/>{s.items.length?s.items.map(x=><div className="card commercial-today-card" key={x.id} onClick={()=>onOpen(x.id)}><div><b>{x.nome_estabelecimento}</b><span>{x.segmento||'Sem segmento'} · {x.cidade||'Sem cidade'}</span></div><div><b>{x.proxima_acao||'Definir próxima ação'}</b><span>{cFmtDT(x.proxima_acao_em)}</span></div><div><CBadge tone={x.temperatura}>{x.temperatura}</CBadge><b>Score {x.score_total}</b></div><button className="btn btn-xs">Abrir lead</button></div>):<div className="commercial-zero">Nada pendente aqui.</div>}</div>)}<div className="commercial-today-section"><CSectionTitle title={`Tarefas vencidas · ${d.tarefas_vencidas.length}`}/>{d.tarefas_vencidas.map(t=><div className="card commercial-today-card" key={t.id} onClick={()=>onOpen(t.lead.id)}><div><b>{t.lead.nome_estabelecimento}</b><span>{t.titulo}</span></div><div><b>Vencida</b><span>{cFmtDT(t.prazo)}</span></div><span></span><button className="btn btn-xs">Abrir</button></div>)}</div></div>}

function ColumnsModal({cols,setCols,onClose}){const all=[['segmento','Segmento'],['instagram','Instagram'],['cidade','Cidade'],['status','Status'],['ultimo','Último contato'],['proxima','Próxima ação'],['responsavel','Responsável'],['score','Score'],['entrada','Data de entrada']];return <CModal title="Colunas da tabela" onClose={onClose}><div className="commercial-checklist">{all.map(([k,l])=><label key={k}><input type="checkbox" checked={cols.includes(k)} onChange={e=>{const n=e.target.checked?[...cols,k]:cols.filter(x=>x!==k);setCols(n);localStorage.setItem('comercial_lead_cols',JSON.stringify(n))}}/>{l}</label>)}</div><div className="modal-footer"><button className="btn btn-envox" onClick={onClose}>Concluir</button></div></CModal>}
function CommercialLeads({onOpen,onNew,meta}){const [items,setItems]=useStateCom([]),[filters,setFilters]=useStateCom({q:'',status:'',segmento:'',cidade:'',responsavel:'',origem:'',min_score:'',com_resposta:'',com_auditoria:'',tag:'',data_de:'',data_ate:'',ultimo_contato_de:'',ultimo_contato_ate:'',proxima_acao_de:'',proxima_acao_ate:''}),[selected,setSelected]=useStateCom([]),[cols,setCols]=useStateCom(()=>{try{return JSON.parse(localStorage.getItem('comercial_lead_cols'))||['segmento','instagram','cidade','status','ultimo','proxima','responsavel','score','entrada']}catch(e){return ['segmento','instagram','cidade','status','ultimo','proxima','responsavel','score','entrada']}}),[colModal,setColModal]=useStateCom(false),[importModal,setImportModal]=useStateCom(false),[busy,setBusy]=useStateCom(false);const load=async()=>{setBusy(true);const p=new URLSearchParams();Object.entries(filters).forEach(([k,v])=>{if(v!=='')p.set(k,v)});try{setItems(await CAPI('/comercial/leads?'+p.toString()))}finally{setBusy(false)}};useEffectCom(()=>{load()},[]);const allSelected=items.length&&selected.length===items.length;const bulk=async(action,value)=>{if(!selected.length)return;await CAPI('/comercial/leads/bulk',{method:'POST',body:JSON.stringify({ids:selected,action,value})});setSelected([]);load()};const getInstagram=x=>x.instagram||'—';return <div><div className="commercial-toolbar"><div className="search"><input placeholder="Buscar lead, segmento, cidade, e-mail…" value={filters.q} onChange={e=>setFilters({...filters,q:e.target.value})} onKeyDown={e=>e.key==='Enter'&&load()}/></div><button className="btn" onClick={load}>Buscar</button><button className="btn" onClick={()=>setColModal(true)}>Colunas</button><button className="btn" onClick={()=>setImportModal(true)}>Importar</button><button className="btn btn-envox" onClick={onNew}>+ Novo lead</button></div><div className="commercial-filterbar"><select value={filters.status} onChange={e=>setFilters({...filters,status:e.target.value})}><option value="">Todos os status</option>{meta.stages.map(x=><option value={x.codigo} key={x.codigo}>{x.nome}</option>)}</select><input placeholder="Segmento" value={filters.segmento} onChange={e=>setFilters({...filters,segmento:e.target.value})}/><input placeholder="Cidade" value={filters.cidade} onChange={e=>setFilters({...filters,cidade:e.target.value})}/><select value={filters.responsavel} onChange={e=>setFilters({...filters,responsavel:e.target.value})}><option value="">Todos os responsáveis</option>{meta.users.map(x=><option value={x.id} key={x.id}>{x.nome}</option>)}</select><select value={filters.origem} onChange={e=>setFilters({...filters,origem:e.target.value})}><option value="">Todas as origens</option>{meta.origens.map(x=><option value={x} key={x}>{cOrigin(x)}</option>)}</select><select value={filters.com_resposta} onChange={e=>setFilters({...filters,com_resposta:e.target.value})}><option value="">Resposta: todos</option><option value="true">Com resposta</option><option value="false">Sem resposta</option></select><select value={filters.com_auditoria} onChange={e=>setFilters({...filters,com_auditoria:e.target.value})}><option value="">Auditoria: todos</option><option value="true">Com auditoria</option><option value="false">Sem auditoria</option></select><select value={filters.tag} onChange={e=>setFilters({...filters,tag:e.target.value})}><option value="">Todas as tags</option>{(meta.tags||[]).map(x=><option value={x.id} key={x.id}>{x.nome}</option>)}</select><label className="commercial-filter-date"><span>Entrada de</span><input type="date" value={filters.data_de} onChange={e=>setFilters({...filters,data_de:e.target.value})}/></label><label className="commercial-filter-date"><span>Entrada até</span><input type="date" value={filters.data_ate} onChange={e=>setFilters({...filters,data_ate:e.target.value})}/></label><label className="commercial-filter-date"><span>Último contato de</span><input type="date" value={filters.ultimo_contato_de} onChange={e=>setFilters({...filters,ultimo_contato_de:e.target.value})}/></label><label className="commercial-filter-date"><span>Último contato até</span><input type="date" value={filters.ultimo_contato_ate} onChange={e=>setFilters({...filters,ultimo_contato_ate:e.target.value})}/></label><label className="commercial-filter-date"><span>Próxima ação de</span><input type="date" value={filters.proxima_acao_de} onChange={e=>setFilters({...filters,proxima_acao_de:e.target.value})}/></label><label className="commercial-filter-date"><span>Próxima ação até</span><input type="date" value={filters.proxima_acao_ate} onChange={e=>setFilters({...filters,proxima_acao_ate:e.target.value})}/></label><input type="number" placeholder="Score mínimo" value={filters.min_score} onChange={e=>setFilters({...filters,min_score:e.target.value})}/><button className="btn btn-sm" onClick={load}>Aplicar filtros</button></div>{selected.length>0&&<div className="commercial-bulk"><b>{selected.length} selecionado(s)</b><select onChange={e=>{if(e.target.value)bulk('status',e.target.value);e.target.value=''}} defaultValue=""><option value="">Alterar status…</option>{meta.stages.map(x=><option value={x.codigo} key={x.codigo}>{x.nome}</option>)}</select><select onChange={e=>{if(e.target.value)bulk('responsavel',e.target.value);e.target.value=''}} defaultValue=""><option value="">Atribuir responsável…</option>{meta.users.map(x=><option value={x.id} key={x.id}>{x.nome}</option>)}</select><button className="btn btn-sm danger-ghost" onClick={()=>confirm('Marcar selecionados como NÃO PROSPECTAR?')&&bulk('nao_prospectar',true)}>Não prospectar</button></div>}<div className="table-wrap"><table className="commercial-leads-table"><thead><tr><th><input type="checkbox" checked={!!allSelected} onChange={e=>setSelected(e.target.checked?items.map(x=>x.id):[])}/></th><th>Nome</th>{cols.includes('segmento')&&<th>Segmento</th>}{cols.includes('instagram')&&<th>Instagram</th>}{cols.includes('cidade')&&<th>Cidade</th>}{cols.includes('status')&&<th>Status</th>}{cols.includes('ultimo')&&<th>Último contato</th>}{cols.includes('proxima')&&<th>Próxima ação</th>}{cols.includes('responsavel')&&<th>Responsável</th>}{cols.includes('score')&&<th>Score</th>}{cols.includes('entrada')&&<th>Entrada</th>}</tr></thead><tbody>{busy?<tr><td colSpan="12">Carregando…</td></tr>:items.length?items.map(x=><tr key={x.id}><td onClick={e=>e.stopPropagation()}><input type="checkbox" checked={selected.includes(x.id)} onChange={e=>setSelected(e.target.checked?[...selected,x.id]:selected.filter(i=>i!==x.id))}/></td><td onClick={()=>onOpen(x.id)} className="commercial-click"><b>{x.nome_estabelecimento}</b><small>{x.nome_fantasia||''}</small></td>{cols.includes('segmento')&&<td>{x.segmento||'—'}</td>}{cols.includes('instagram')&&<td>{getInstagram(x)}</td>}{cols.includes('cidade')&&<td>{x.cidade||'—'}</td>}{cols.includes('status')&&<td><CBadge>{cStatus(x.status_codigo)}</CBadge></td>}{cols.includes('ultimo')&&<td>{cFmtDate(x.ultimo_contato_em)}</td>}{cols.includes('proxima')&&<td>{x.proxima_acao||'—'}<small>{cFmtDT(x.proxima_acao_em)}</small></td>}{cols.includes('responsavel')&&<td>{x.responsavel_nome||'—'}</td>}{cols.includes('score')&&<td><b>{x.score_total}</b></td>}{cols.includes('entrada')&&<td>{cFmtDate(x.data_entrada)}</td>}</tr>):<tr><td colSpan="12"><CEmpty>Nenhum lead encontrado.</CEmpty></td></tr>}</tbody></table></div>{colModal&&<ColumnsModal cols={cols} setCols={setCols} onClose={()=>setColModal(false)}/>} {importModal&&<ImportModal onClose={()=>setImportModal(false)} onDone={()=>{setImportModal(false);load()}}/>}</div>}

function CommercialPipeline({onOpen,meta}){const [leads,setLeads]=useStateCom([]),[drag,setDrag]=useStateCom(null);const load=()=>CAPI('/comercial/leads').then(setLeads);useEffectCom(()=>{load()},[]);const cols=['novo','em_analise','pronto_abordagem','mensagem_1_enviada','respondeu','em_conversa','oportunidade','reuniao_agendada','proposta','negociacao','ganho','perdido'];const drop=async code=>{if(!drag)return;await CAPI(`/comercial/leads/${drag}`,{method:'PATCH',body:JSON.stringify({status_codigo:code})});setDrag(null);load()};return <div className="commercial-pipeline">{cols.map(code=>{const st=meta.stages.find(s=>s.codigo===code);const ls=leads.filter(l=>l.status_codigo===code);return <div className="commercial-pipe-col" key={code} onDragOver={e=>e.preventDefault()} onDrop={()=>drop(code)}><div className="commercial-pipe-head">{st?.nome||cStatus(code)} <span>{ls.length}</span></div>{ls.map(l=><div draggable className="commercial-pipe-card" key={l.id} onDragStart={()=>setDrag(l.id)} onClick={()=>onOpen(l.id)}><div className="commercial-pipe-score">{l.score_total}</div><b>{l.nome_estabelecimento}</b><div className="muted">{l.segmento||'—'} · {l.cidade||'—'}</div>{l.proxima_acao&&<div className="commercial-pipe-next">{l.proxima_acao}<small>{cFmtDate(l.proxima_acao_em)}</small></div>}</div>)}</div>})}</div>}

function CommercialConversations({onOpen}){const [items,setItems]=useStateCom(null);useEffectCom(()=>{CAPI('/comercial/conversas').then(setItems)},[]);if(!items)return <CSpinner/>;return <div className="commercial-conversation-list">{items.length?items.map(x=><div className={'card commercial-conv-row '+(x.aguardando_acao?'attention':'')} key={x.lead.id} onClick={()=>onOpen(x.lead.id)}><div><b>{x.lead.nome_estabelecimento}</b><span>{cStatus(x.lead.status_codigo)} · {x.lead.responsavel_nome||'Sem responsável'}</span></div><div className="commercial-conv-preview">{x.ultima_mensagem.conteudo}</div><div><CBadge>{x.ultima_mensagem.direcao}</CBadge><span>{cFmtDT(x.ultima_mensagem.enviado_em)}</span></div></div>):<CEmpty>Nenhuma conversa registrada.</CEmpty>}</div>}

function CadenceEditor({cadence,onClose,onDone}){const [name,setName]=useStateCom(cadence?.nome||''),[desc,setDesc]=useStateCom(cadence?.descricao||''),[steps,setSteps]=useStateCom(cadence?.steps?.map(x=>({ordem:x.ordem,dias_apos_inicio:x.dias_apos_inicio,tipo:x.tipo,orientacao:x.orientacao||''}))||[{dias_apos_inicio:0,tipo:'abordagem',orientacao:'Mensagem inicial com primeiro ouro.'},{dias_apos_inicio:2,tipo:'follow_up',orientacao:'Nova evidência ou ouro.'}]),[error,setError]=useStateCom('');const save=async()=>{try{await CAPI(cadence?`/comercial/cadencias/${cadence.id}`:'/comercial/cadencias',{method:cadence?'PATCH':'POST',body:JSON.stringify({nome:name,descricao:desc,steps})});onDone()}catch(e){setError(e.message)}};return <CModal title={cadence?'Editar cadência':'Nova cadência'} onClose={onClose} wide><CError error={error}/><div className="form-grid"><CField label="Nome"><input value={name} onChange={e=>setName(e.target.value)}/></CField><CField label="Descrição"><input value={desc} onChange={e=>setDesc(e.target.value)}/></CField></div><CSectionTitle title="Etapas" action={<button className="btn btn-xs" onClick={()=>setSteps([...steps,{dias_apos_inicio:steps.length?steps[steps.length-1].dias_apos_inicio+3:0,tipo:'follow_up',orientacao:''}])}>+ Etapa</button>}/><div className="commercial-cadence-edit">{steps.map((s,i)=><div key={i}><input type="number" value={s.dias_apos_inicio} onChange={e=>setSteps(steps.map((x,j)=>j===i?{...x,dias_apos_inicio:Number(e.target.value)}:x))}/><select value={s.tipo} onChange={e=>setSteps(steps.map((x,j)=>j===i?{...x,tipo:e.target.value}:x))}><option value="abordagem">Abordagem</option><option value="follow_up">Follow-up</option><option value="reativacao">Reativação</option></select><input value={s.orientacao} onChange={e=>setSteps(steps.map((x,j)=>j===i?{...x,orientacao:e.target.value}:x))}/><button className="icon-btn" onClick={()=>setSteps(steps.filter((_,j)=>j!==i))}>×</button></div>)}</div><div className="modal-footer"><button className="btn" onClick={onClose}>Cancelar</button><button className="btn btn-envox" onClick={save} disabled={!name.trim()||!steps.length}>{cadence?'Salvar cadência':'Criar cadência'}</button></div></CModal>}
function CommercialCadences({permission}){const [items,setItems]=useStateCom(null),[editor,setEditor]=useStateCom(null);const load=()=>CAPI('/comercial/cadencias').then(setItems);useEffectCom(()=>{load()},[]);if(!items)return <CSpinner/>;return <div><CSectionTitle title="Cadências de prospecção" action={permission!=='envoxer'?<button className="btn btn-envox" onClick={()=>setEditor({})}>+ Nova cadência</button>:null}/><div className="commercial-cadence-list">{items.map(c=><div className="card" key={c.id}><div className="commercial-cadence-head"><div><h3>{c.nome}</h3><span>{c.descricao}</span></div><div><CBadge tone={c.ativa?'quente':''}>{c.ativa?'Ativa':'Inativa'}</CBadge><b>{c.leads_ativos} em andamento</b>{permission!=='envoxer'&&<button className="btn btn-xs" onClick={()=>setEditor(c)}>Editar</button>}</div></div><div className="commercial-steps compact">{c.steps.map(s=><div className="commercial-step" key={s.id}><b>D{s.dias_apos_inicio}</b><span>{cStatus(s.tipo)}</span><small>{s.orientacao}</small></div>)}</div></div>)}</div>{editor&&<CadenceEditor cadence={editor.id?editor:null} onClose={()=>setEditor(null)} onDone={()=>{setEditor(null);load()}}/>}</div>}

function CommercialTasks({onOpen}){const [items,setItems]=useStateCom(null),[filter,setFilter]=useStateCom('pendente');const load=()=>CAPI('/comercial/tarefas'+(filter?`?status=${filter}`:'')).then(setItems);useEffectCom(()=>{load()},[filter]);if(!items)return <CSpinner/>;return <div><div className="commercial-toolbar"><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="pendente">Pendentes</option><option value="concluida">Concluídas</option><option value="">Todas</option></select></div><div className="card"><div className="table-wrap"><table><thead><tr><th></th><th>Tarefa</th><th>Lead</th><th>Responsável</th><th>Prazo</th><th>Status</th></tr></thead><tbody>{items.map(t=><tr key={t.id}><td><button className={'commercial-check '+(t.status==='concluida'?'done':'')} onClick={async()=>{await CAPI(`/comercial/tarefas/${t.id}`,{method:'PATCH',body:JSON.stringify({status:t.status==='concluida'?'pendente':'concluida'})});load()}}>{t.status==='concluida'?'✓':''}</button></td><td><b>{t.titulo}</b><small>{t.descricao}</small></td><td className="commercial-click" onClick={()=>onOpen(t.lead_id)}>{t.lead_nome}</td><td>{t.responsavel_nome||'—'}</td><td className={t.status==='pendente'&&t.prazo&&new Date(t.prazo)<new Date()?'overdue':''}>{cFmtDT(t.prazo)}</td><td><CBadge>{t.status}</CBadge></td></tr>)}</tbody></table></div></div></div>}

function CommercialOpportunities({onOpen}){const [items,setItems]=useStateCom(null);useEffectCom(()=>{CAPI('/comercial/oportunidades').then(setItems)},[]);if(!items)return <CSpinner/>;const total=items.reduce((s,x)=>s+Number(x.valor_estimado||0),0);return <div><div className="commercial-opportunity-summary"><div><span>Oportunidades</span><b>{items.length}</b></div><div><span>Pipeline estimado</span><b>{cMoney(total)}</b></div><div><span>Probabilidade média</span><b>{items.length?Math.round(items.reduce((s,x)=>s+x.probabilidade,0)/items.length):0}%</b></div></div><div className="card"><div className="table-wrap"><table><thead><tr><th>Lead</th><th>Dor principal</th><th>Solução provável</th><th>Valor</th><th>Prob.</th><th>Etapa</th><th>Previsão</th></tr></thead><tbody>{items.map(o=><tr key={o.id} onClick={()=>onOpen(o.lead_id)} className="commercial-click"><td><b>{o.lead_nome}</b></td><td>{o.dor_principal||'—'}</td><td>{o.solucao_provavel||'—'}</td><td>{cMoney(o.valor_estimado)}</td><td>{o.probabilidade}%</td><td><CBadge>{cStatus(o.etapa)}</CBadge></td><td>{cFmtDate(o.data_prevista)}</td></tr>)}</tbody></table></div></div></div>}

function CReportTable({title,rows,cols}){return <div className="card"><CSectionTitle title={title}/>{rows?.length?<div className="table-wrap"><table><thead><tr>{cols.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{cols.map(c=><td key={c.key}>{c.format?c.format(r[c.key]):r[c.key]??'—'}</td>)}</tr>)}</tbody></table></div>:<div className="muted">Ainda não há dados suficientes.</div>}</div>}
function CommercialReports(){const [d,setD]=useStateCom(null);useEffectCom(()=>{CAPI('/comercial/relatorios').then(setD)},[]);if(!d)return <CSpinner/>;return <div><div className="commercial-report-kpis">{Object.entries(d.metricas).map(([k,v])=><div className="kpi" key={k}><div className="kpi-label">{cStatus(k)}</div><div className="kpi-value">{String(v).includes('.')?v:v}{k.startsWith('taxa_')?'%':''}</div></div>)}</div><div className="commercial-report-grid"><CReportTable title="WhatsApp x Instagram x E-mail" rows={d.por_canal} cols={[{key:'canal',label:'Canal',format:cChannel},{key:'enviadas',label:'Enviadas'},{key:'leads_responderam',label:'Leads que responderam'},{key:'taxa_resposta',label:'Taxa',format:v=>v+'%'}]}/><CReportTable title="Tipos de ouro" rows={d.por_ouro} cols={[{key:'categoria',label:'Categoria',format:cStatus},{key:'utilizados',label:'Usados'},{key:'leads_que_responderam',label:'Responderam'},{key:'taxa_resposta',label:'Taxa',format:v=>v+'%'}]}/><CReportTable title="Segmentos" rows={d.por_segmento} cols={[{key:'segmento',label:'Segmento'},{key:'leads',label:'Leads'},{key:'responderam',label:'Responderam'},{key:'reunioes',label:'Reuniões'},{key:'ganhos',label:'Ganhos'},{key:'taxa_resposta',label:'Taxa',format:v=>v+'%'}]}/><CReportTable title="Cidades" rows={d.por_cidade} cols={[{key:'cidade',label:'Cidade'},{key:'leads',label:'Leads'},{key:'responderam',label:'Responderam'},{key:'ganhos',label:'Ganhos'},{key:'taxa_resposta',label:'Taxa',format:v=>v+'%'}]}/><CReportTable title="Responsáveis" rows={d.por_responsavel} cols={[{key:'responsavel',label:'Responsável'},{key:'leads',label:'Leads'},{key:'responderam',label:'Responderam'},{key:'ganhos',label:'Ganhos'},{key:'taxa_resposta',label:'Taxa',format:v=>v+'%'}]}/></div></div>}

function IntegrationConfigModal({integration,onClose,onDone}){
  const [pub,setPub]=useStateCom(()=>({...integration.config_publica}));
  const [secrets,setSecrets]=useStateCom({});
  const [active,setActive]=useStateCom(!!integration.ativo);
  const [busy,setBusy]=useStateCom('');
  const [error,setError]=useStateCom('');
  const [notice,setNotice]=useStateCom('');
  const setPublic=(k,v)=>setPub(x=>({...x,[k]:v}));
  const setSecret=(k,v)=>setSecrets(x=>({...x,[k]:v}));
  const fieldInput=(f,secret=false)=>{
    const value=secret?(secrets[f.key]||''):(pub[f.key]??f.default??'');
    const common={value,onChange:e=>secret?setSecret(f.key,e.target.value):setPublic(f.key,f.type==='number'&&e.target.value!==''?Number(e.target.value):e.target.value),placeholder:secret&&integration.secret_status?.[f.key]?'Já configurado — deixe em branco para manter':(f.placeholder||'')};
    if(f.type==='select')return <select {...common}>{(f.options||[]).map(o=><option value={o.value} key={o.value}>{o.label}</option>)}</select>;
    return <input {...common} type={secret?'password':(f.type||'text')} autoComplete={secret?'new-password':undefined}/>;
  };
  const save=async(test=false)=>{
    setBusy(test?'test':'save');setError('');setNotice('');
    try{
      await CAPI(`/comercial/integracoes/${integration.provider}`,{method:'PATCH',body:JSON.stringify({ativo:active,config_publica:pub,segredos:Object.fromEntries(Object.entries(secrets).filter(([,v])=>v!==''))})});
      if(test){const r=await CAPI(`/comercial/integracoes/${integration.provider}/testar`,{method:'POST'});setNotice(r.mensagem||'Conexão validada com sucesso.');await onDone(false)}
      else{await onDone(true)}
    }catch(e){setError(e.message||'Não foi possível salvar a integração.')}finally{setBusy('')}
  };
  const clear=async()=>{if(!confirm('Apagar todas as credenciais desta integração? Ela será desativada.'))return;setBusy('clear');setError('');try{await CAPI(`/comercial/integracoes/${integration.provider}/credenciais`,{method:'DELETE'});await onDone(true)}catch(e){setError(e.message)}finally{setBusy('')}};
  return <CModal title={`Configurar · ${integration.nome}`} onClose={onClose} wide>
    <div className="commercial-integration-modal-intro"><div><b>{integration.nome}</b><span>{integration.descricao}</span></div><CBadge tone={integration.configurado?'quente':''}>{integration.configurado?'Configurada':'Pendente'}</CBadge></div>
    {integration.fonte_credencial==='ambiente'&&<div className="commercial-integration-env-note">A credencial atual da OpenAI foi encontrada no <code>.env</code> do Envoxers. Você pode mantê-la assim ou informar uma nova chave abaixo para passar a gerenciá-la pelo painel.</div>}
    <CError error={error}/>{notice&&<div className="commercial-integration-success">{notice}</div>}
    <div className="commercial-form-block"><h4>Configuração</h4><div className="form-grid">{(integration.campos_publicos||[]).map(f=><CField label={`${f.label}${f.required?' *':''}`} key={f.key}>{fieldInput(f,false)}{f.help&&<small className="field-help">{f.help}</small>}</CField>)}</div></div>
    {(integration.campos_secretos||[]).length>0&&<div className="commercial-form-block"><h4>Credenciais secretas</h4><div className="form-grid">{integration.campos_secretos.map(f=><CField label={`${f.label}${f.required?' *':''}`} key={f.key}>{fieldInput(f,true)}<small className="field-help">{integration.secret_status?.[f.key]?'Credencial já armazenada com segurança. Preencha somente para substituir.':(f.help||'O valor será armazenado criptografado e não será exibido novamente.')}</small></CField>)}</div></div>}
    <div className="commercial-integration-toggle"><div><b>Integração ativa</b><span>Desative sem apagar as credenciais quando quiser interromper temporariamente o uso.</span></div><label className="switch"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/><span></span></label></div>
    <div className="commercial-integration-test-state"><b>Último teste</b><span>{integration.ultimo_teste_em?cFmtDT(integration.ultimo_teste_em):'Ainda não testada'}</span>{integration.ultimo_teste_ok===true&&<CBadge tone="quente">Conexão OK</CBadge>}{integration.ultimo_teste_ok===false&&<CBadge>Falhou</CBadge>}{integration.ultimo_erro&&<small>{integration.ultimo_erro}</small>}</div>
    <div className="modal-footer commercial-integration-footer">{integration.configurado&&<button className="btn danger-ghost" onClick={clear} disabled={!!busy}>{busy==='clear'?'Apagando…':'Apagar credenciais'}</button>}<span></span><button className="btn" onClick={onClose}>Cancelar</button><button className="btn" onClick={()=>save(true)} disabled={!!busy}>{busy==='test'?'Testando…':'Salvar e testar'}</button><button className="btn btn-envox" onClick={()=>save(false)} disabled={!!busy}>{busy==='save'?'Salvando…':'Salvar configuração'}</button></div>
  </CModal>
}

function CommercialConfig({meta}){
  const [d,setD]=useStateCom(null),[stages,setStages]=useStateCom(meta.stages||[]),[newStage,setNewStage]=useStateCom(false),[integrationModal,setIntegrationModal]=useStateCom(null),[error,setError]=useStateCom('');
  const canManage=meta.permission!=='envoxer';
  const canManageIntegrations=meta.permission==='admin';
  const load=()=>CAPI('/comercial/config').then(setD).catch(e=>setError(e.message));
  useEffectCom(()=>{load()},[]);
  if(!d)return error?<CError error={error}/>:<CSpinner/>;
  const createStage=async f=>{const x=await CAPI('/comercial/stages',{method:'POST',body:JSON.stringify({nome:f.nome,codigo:f.codigo||f.nome,ordem:Number(f.ordem||999),tipo:f.tipo||'aberto'})});setStages(xs=>[...xs,x].sort((a,b)=>a.ordem-b.ordem));setNewStage(false)};
  const removeSuppression=async id=>{if(!confirm('Remover este contato da lista de não contatar?'))return;await CAPI(`/comercial/suppression/${id}`,{method:'DELETE'});load()};
  return <div className="commercial-config">
    <div className="card span-2"><CSectionTitle title="Integrações"/>{!canManageIntegrations&&<div className="muted" style={{marginBottom:10}}>Somente administradores podem cadastrar ou alterar credenciais de integrações.</div>}<div className="commercial-integrations">{d.integracoes.map(x=><div key={x.id}><div className={'commercial-integration-dot '+(x.configurado&&x.ativo?'ok':'')}></div><div><b>{x.nome}</b><span>{x.descricao}</span><small>{x.configurado?(x.ativo?'Configurada e ativa':'Configurada, mas desativada'):'Ainda não configurada'}{x.fonte_credencial==='ambiente'?' · credencial via .env':''}</small></div><div className="commercial-integration-actions"><CBadge tone={x.configurado&&x.ativo?'quente':''}>{x.configurado?(x.ativo?'Ativa':'Inativa'):'Pendente'}</CBadge>{canManageIntegrations&&<button className="btn btn-sm" onClick={()=>setIntegrationModal(x)}>Configurar</button>}</div></div>)}</div></div>
    <div className="card"><CSectionTitle title="Tags cadastradas"/>{d.tags?.length?<div className="commercial-tag-list">{d.tags.map(x=><CBadge key={x.id}>{x.nome}</CBadge>)}</div>:<div className="muted">As tags aparecem aqui à medida que forem criadas nos leads.</div>}</div>
    <div className="card span-2"><CSectionTitle title="Pipeline editável" action={canManage?<button className="btn btn-envox btn-sm" onClick={()=>setNewStage(true)}>+ Novo status</button>:null}/>{!canManage&&<div className="muted" style={{marginBottom:8}}>Somente gestor e admin podem alterar a estrutura do pipeline.</div>}<div className="commercial-stage-list">{stages.map(x=><div key={x.id}><input value={x.nome} readOnly={!canManage} onChange={e=>setStages(xs=>xs.map(y=>y.id===x.id?{...y,nome:e.target.value}:y))} onBlur={async e=>{if(canManage){const y=await CAPI(`/comercial/stages/${x.id}`,{method:'PATCH',body:JSON.stringify({nome:e.target.value})});setStages(xs=>xs.map(z=>z.id===x.id?{...z,...y}:z))}}}/><input type="number" value={x.ordem} readOnly={!canManage} onChange={e=>setStages(xs=>xs.map(y=>y.id===x.id?{...y,ordem:Number(e.target.value)}:y))} onBlur={async e=>{if(canManage){const y=await CAPI(`/comercial/stages/${x.id}`,{method:'PATCH',body:JSON.stringify({ordem:Number(e.target.value)})});setStages(xs=>xs.map(z=>z.id===x.id?{...z,...y}:z).sort((a,b)=>a.ordem-b.ordem))}}}/><CBadge>{x.tipo}</CBadge></div>)}</div></div>
    <div className="card span-2"><CSectionTitle title="Lista de supressão / não contatar"/><div className="table-wrap"><table><thead><tr><th>Lead</th><th>Tipo</th><th>Valor</th><th>Motivo</th><th>Data</th>{canManage&&<th>Ação</th>}</tr></thead><tbody>{d.suppression_list.length?d.suppression_list.map(x=><tr key={x.id}><td>{x.lead_nome||'—'}</td><td>{cStatus(x.tipo)}</td><td>{x.valor}</td><td>{x.motivo||'—'}</td><td>{cFmtDate(x.created_at)}</td>{canManage&&<td><button className="btn btn-xs" onClick={()=>removeSuppression(x.id)}>Remover</button></td>}</tr>):<tr><td colSpan={canManage?6:5}><div className="muted">Nenhum contato na lista de supressão.</div></td></tr>}</tbody></table></div></div>
    {integrationModal&&<IntegrationConfigModal integration={integrationModal} onClose={()=>setIntegrationModal(null)} onDone={async close=>{await load();if(close)setIntegrationModal(null);else{const fresh=await CAPI('/comercial/integracoes');const item=fresh.find(x=>x.provider===integrationModal.provider);if(item)setIntegrationModal(item)}}}/>}
    {newStage&&<SimpleFormModal title="Novo status comercial" onClose={()=>setNewStage(false)} fields={[{key:'nome',label:'Nome do status'},{key:'codigo',label:'Código (opcional)'},{key:'ordem',label:'Ordem',type:'number',value:'999'},{key:'tipo',label:'Tipo',type:'select',value:'aberto',options:[{value:'aberto',label:'Aberto'},{value:'contato',label:'Contato'},{value:'oportunidade',label:'Oportunidade'},{value:'fechado',label:'Fechado'}]}]} onSave={createStage}/>}
  </div>
}

function ComercialScreen({mode='dashboard'}){
  const [leadId,setLeadId]=useStateCom(null),[newLead,setNewLead]=useStateCom(false),[meta,setMeta]=useStateCom(commercialMetaCache),[metaError,setMetaError]=useStateCom(''),[version,setVersion]=useStateCom(0);
  useEffectCom(()=>{let active=true;if(!meta){CLoadMeta().then(r=>{if(active)setMeta(r)}).catch(e=>{if(active)setMetaError(e.message||'Não foi possível carregar o Comercial')})}return()=>{active=false}},[]);
  if(!meta)return <div className="page commercial-page">{metaError?<CError error={metaError}/>:<CSpinner/>}</div>;
  if(leadId)return <div className="page commercial-page"><LeadDetail leadId={leadId} onBack={()=>setLeadId(null)} meta={meta}/></div>;
  const titles={dashboard:['Dashboard','Visão do funil, conversão e prioridades da prospecção.'],hoje:['Prospecções de hoje','Quem precisa de ação agora, em uma única rotina.'],leads:['Leads','Base única de estabelecimentos e histórico comercial.'],pipeline:['Pipeline comercial','Movimente os leads sem perder a linha do tempo.'],conversas:['Conversas','Últimas interações e respostas aguardando ação.'],cadencias:['Cadências','Sequências de contato com uma nova razão comercial em cada etapa.'],tarefas:['Tarefas','Pendências comerciais com responsável e prazo.'],oportunidades:['Oportunidades','Potenciais negócios já convertidos em oportunidade comercial.'],relatorios:['Relatórios','O que está gerando resposta, reunião e fechamento.'],config:['Configurações comerciais','Pipeline, integrações, tags e lista de não contato.']};
  const [title,sub]=titles[mode]||titles.dashboard;
  return <div className="page commercial-page" key={version}><EnvoxersShared.PageHeader title={title} subtitle={sub} actions={!['config','relatorios','cadencias'].includes(mode)?<button className="btn btn-envox" onClick={()=>setNewLead(true)}>+ Novo lead</button>:null}/>{mode==='dashboard'&&<CommercialDashboard onOpen={setLeadId}/>} {mode==='hoje'&&<CommercialToday onOpen={setLeadId}/>} {mode==='leads'&&<CommercialLeads onOpen={setLeadId} onNew={()=>setNewLead(true)} meta={meta}/>} {mode==='pipeline'&&<CommercialPipeline onOpen={setLeadId} meta={meta}/>} {mode==='conversas'&&<CommercialConversations onOpen={setLeadId}/>} {mode==='cadencias'&&<CommercialCadences permission={meta.permission}/>} {mode==='tarefas'&&<CommercialTasks onOpen={setLeadId}/>} {mode==='oportunidades'&&<CommercialOpportunities onOpen={setLeadId}/>} {mode==='relatorios'&&<CommercialReports/>} {mode==='config'&&<CommercialConfig meta={meta}/>} {newLead&&<LeadFormModal meta={meta} onClose={()=>setNewLead(false)} onSaved={()=>{setNewLead(false);setVersion(v=>v+1)}}/>}</div>
}
window.ComercialScreen=ComercialScreen;
